INSERT INTO cms.review (id, author_en, author_ar, company_en, company_ar, quote_en, quote_ar, rating, is_approved, sort_order, year, created_at) VALUES ('34c20581-fd8d-4c9d-a9bd-b6b30356dd30', 'Eng. Salman Al-Moayyed', 'م. سلمان المؤيد', 'Almoayyed Contracting Group W.L.L.', 'مجموعة المؤيد للمقاولات ذ.م.م', 'Al-Shifa Clinic consistently delivers on complex Bahrain commercial schedules with transparent VAT documentation and responsive bilingual account leads.', 'تلتزم عيادة الشفاء دائماً بالجداول الزمنية للمشاريع التجارية في البحرين مع توثيق ضريبي شفاف وفريق حسابات سريع الاستجابة.', 5, true, 20, 2026, now() - interval '15 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.review (id, author_en, author_ar, company_en, company_ar, quote_en, quote_ar, rating, is_approved, sort_order, year, created_at) VALUES ('1cee1d8e-fc2b-4a6a-ac36-04b0fb2d5316', 'Dr. Hessa Al-Zayani', 'د. حصة الزياني', 'Dilmunia Health & Wellness Center', 'مركز دلمونيا للصحة والعافية', 'From initial quotation to final commissioning, the Al-Shifa Clinic operations team exceeded our SLA expectations.', 'من عرض السعر الأولي حتى التسليم النهائي، تجاوز فريق عمليات عيادة الشفاء توقعاتنا في الالتزام بمستوى الخدمة.', 5, true, 21, 2026, now() - interval '20 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('2e674d36-69b4-475c-a159-baacbbeba2c2', 'Are all Al-Shifa Clinic invoices compliant with Bahrain NBR 10% VAT regulations?', 'هل جميع فواتير عيادة الشفاء متوافقة مع لوائح ضريبة القيمة المضافة 10% في البحرين؟', 'Yes. Every quotation and tax invoice includes our registered VAT ID (200012204500002), itemized tax calculations, and verifiable QR metadata.', 'نعم، تتضمن كل فاتورة ضريبية وعرض سعر رقمنا الضريبي المسجل (200012204500002) مع تفصيل الضريبة ورمز التحقق.', 'billing', true, 20, now() - interval '20 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('fc8a23ac-b9dc-487d-a7cd-a6562d85593a', 'Which Bahrain governorates and GCC destinations do you cover?', 'ما هي المحافظات في البحرين ووجهات الخليج التي تغطونها؟', 'We provide same-day and next-day fulfillment across Capital, Muharraq, Northern, and Southern Governorates, plus scheduled cross-border freight to Saudi Arabia, UAE, Qatar, Kuwait, and Oman.', 'نوفر التوصيل في نفس اليوم أو اليوم التالي في جميع محافظات البحرين، بالإضافة إلى الشحن المجدول لدول مجلس التعاون الخليجي.', 'logistics', true, 21, now() - interval '23 days') ON CONFLICT (id) DO NOTHING;
